LEARNING['http_endpoints'] = (
    'Ready Pods can still fail to serve application traffic. Every stable and canary backend needs a working HTTP server.',
    'Inspect the Service endpoints and test each Pod address from a stable Pod. Keep the stable and canary replica counts and labels as requested.')


def learning_feedback(task, check, status):
    kind = check['kind']
    concept, next_step = LEARNING[kind]
    namespace = check.get('namespace') or task['namespace']
    k = ['kubectl', '-n', namespace]
    command = k + ['get', 'pods']
    focus = ''
    if kind in ('resource', 'ready'):
        resource, name = check['resource'], check['name']
        command = k + ['describe' if kind == 'ready' else 'get', resource, name]
        if kind == 'resource' and resource.lower() not in ('secret', 'secrets'):
            command += ['-o', 'yaml']
        path = check.get('items_path', []) + (['[application container]'] if 'items_path' in check else []) + check.get('path', [])
        focus = '.'.join('[' + ', '.join(f'{key}={value}' for key, value in part.items()) + ']' if isinstance(part, dict) else str(part) for part in path)
        if isinstance(check.get('expected'), dict):
            focus += (' → ' if focus else '') + ', '.join(check['expected'])
    elif kind == 'inventory': command = k + ['get', check['resource']]
    elif kind == 'rollout_history': command = k + ['rollout', 'history', 'deployment/' + check['name']]
    elif kind == 'job_complete': command = k + ['describe', 'job', check['name']]
    elif kind == 'exec': command = k + ['describe', 'pod', check['pod']]
    elif kind == 'logs':
        command = k + ['logs', check['resource'], '--tail=30']
        if check.get('container'): command += ['-c', check['container']]
    elif kind in ('file', 'yaml_file', 'metrics_file'): command = ['cat', check['path']]
    elif kind == 'render': command = ['kubectl', 'kustomize', check['path']]
    elif kind in ('endpoints','http_endpoints'): command = k + ['get', 'endpointslices', '-l', 'kubernetes.io/service-name=' + check['name'], '-o', 'yaml']
    elif kind == 'http': command = k + ['exec', check['source'], '--', 'wget', '-T', '5', '-q', '-O-', check['url']]
    elif kind == 'http_nodeport': command = k + ['get', 'service', check['service'], '-o', 'jsonpath={.spec.ports[0].nodePort}']
    elif kind == 'http_external':
        command = ['curl', '--max-time', '10']
        if check.get('host'): command += ['-H', 'Host: ' + check['host']]
        command += [check['url']]
    elif kind == 'traffic': command = k + ['get', 'networkpolicy', '-o', 'yaml']
    elif kind == 'auth':
        resource = check['resource'].split('/')
        command = ['kubectl', '-n', check.get('target_namespace') or task['namespace'], 'auth', 'can-i', check['verb'], resource[0], '--as=system:serviceaccount:' + task['namespace'] + ':' + check['sa']]
        if len(resource) > 1: command += ['--subresource=' + resource[1]]
    elif kind == 'rbac_rules': command = k + ['get', 'role', check['name'], '-o', 'yaml']
    elif kind == 'admission_denied': command = k + ['get', 'namespace', task['namespace'], '--show-labels']
    elif kind == 'helm': command = ['helm', '-n', task['namespace'], 'get', 'values', check['release'], '--all']
    elif kind in ('image', 'image_base', 'image_same', 'image_file'):
        command = ['docker', 'image', 'inspect', check['image']]
        if kind == 'image_same': command.append(check['other'])
    elif kind == 'image_archive': command = ['tar', '-tf', check['path']]
    if status == 'pass':
        next_step = 'This checkpoint is satisfied in the last observed state. Continue to the next requirement, and recheck if you change this resource or one of its dependencies.'
    elif status == 'error':
        next_step = 'This check could not be evaluated; it is not evidence that your answer is wrong. Read the diagnostic, check Lab status, resolve the tool or cluster issue, then retry.'
    return {'concept': concept, 'next': next_step, 'command': join(command), 'focus': focus}
